package dev.jobflow.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="job_attempts") public class JobAttempt { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="job_id",nullable=false) private Job job; @Column(name="attempt_number",nullable=false) private int attemptNumber; @Column(name="started_at",nullable=false) private Instant startedAt; @Column(name="finished_at") private Instant finishedAt; private String outcome; @Column(name="error_message") private String errorMessage; protected JobAttempt(){} public JobAttempt(Job job){id=UUID.randomUUID();this.job=job;attemptNumber=job.getAttemptCount();startedAt=Instant.now();} public void finish(String outcome,String error){this.outcome=outcome;errorMessage=error;finishedAt=Instant.now();} }
